import csv
import json
import os

VALID_CATEGORIES = {'grocery', 'travel', 'salary', 'rent', 'other'}

def is_valid_row(row):
    try:
        amount = row['amount']
        if amount == '':
            return False
        amount = float(amount)
        if not (0 <= amount <= 10000):
            return False
        if row['category'] not in VALID_CATEGORIES:
            return False
        return True
    except (ValueError, KeyError):
        return False

valid_rows = []
rejected_row_ids = []

with open('data/events.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if is_valid_row(row):
            valid_rows.append(row)
        else:
            rejected_row_ids.append(row['row_id'])

os.makedirs('submission', exist_ok=True)
with open('submission/answers.json', 'w') as f:
    json.dump({'rejected': rejected_row_ids}, f, indent=2)

print('Filtered rows and wrote submission/answers.json')
